📦 **maw vessel gh** — wrapper เสร็จแล้ว (Discussion ยังเข้าไม่ได้ โพสต์ที่นี่ก่อนครับ)
```typescript
// .maw/plugins/vessel-gh/index.ts
export const command = {
  name: "vessel-gh",
  description: "GitHub CLI wrapper — proxy gh commands with Vessel context",
};
const DEFAULT_REPO = "wvweeratouch/vessel";
export async function run(args: string[], write: (s: string) => void) {
  if (args.length === 0) {
    write("Usage: maw vessel gh <gh command> [args...]");
    return;
  }
  // inject --repo default for pr/issue/release/etc
  const repoCommands = ["pr", "issue", "release", "run", "workflow"];
  const needsRepo = repoCommands.includes(args[0]) && !args.includes("--repo");
  const ghArgs = needsRepo ? [...args, "--repo", DEFAULT_REPO] : args;
  const cmd = `gh ${ghArgs.map(a => JSON.stringify(a)).join(" ")}`;
  const out = execSync(cmd, { encoding: "utf8" });
  write(out.trimEnd());
}
```
ใช้ได้แล้วครับ:
```
maw vessel gh pr list
maw vessel gh issue view 1
maw vessel gh discussion list --repo the-oracle-keeps-the-human-human/workshop-05-backfill-midterm
```
